1	const jwt = require('jsonwebtoken');
2	
3	const verifyToken = async (req, res, next) => {
4	    // 1. Grab the token from the request header
5	    const authHeader = req.headers['authorization'];
6	
7	    // Tokens usually come in as "Bearer <token_string>", so we split it to just get the string
8	    const token = authHeader && authHeader.split(' ')[1];
9	
10	    // 2. If there is no token, kick them out
11	    if (!token) {
12	        return res.status(401).json({ message: "Access Denied. No security token provided." });
13	    }
14	
15	    // 3. Verify the token signature/expiry
16	    let decoded;
17	    try {
18	        decoded = jwt.verify(token, process.env.APP_SECRET);
19	    } catch (err) {
20	        return res.status(403).json({ message: "Invalid or expired security token." });
21	    }
22	
23	    try {
24	        // 4. The DATABASE is authoritative, not the JWT payload. Every protected
25	        //    request re-reads the account so that deletion, suspension, role
26	        //    changes, and session revocation (tokenVersion bump on password
27	        //    change/reset or suspension) take effect immediately — e.g. a
28	        //    stolen/lost-device token dies the moment the account is secured.
29	        //    Lazy-required so unit tests can jest.mock('../models'); suites that
30	        //    stub the models without a User model keep the JWT-only behaviour.
31	        const { User } = require('../models');
32	        if (User && typeof User.findByPk === 'function') {
33	            const account = await User.findByPk(decoded.id);
34	            if (!account) {
35	                return res.status(401).json({ message: "Account no longer exists. Session terminated." });
36	            }
37	            if (account.isActive === false) {
38	                return res.status(403).json({ message: "Account suspended. Session terminated." });
39	            }
40	            const issuedVersion = Number(decoded.tokenVersion ?? 0);
41	            const currentVersion = Number(account.tokenVersion ?? 0);
42	            if (issuedVersion !== currentVersion) {
43	                return res.status(401).json({ message: "Session revoked. Please log in again." });
44	            }
45	            req.user = {
46	                id: account.id,
47	                email: account.email,
48	                role: account.role,          // DB role wins over whatever the JWT claims
49	                tokenVersion: currentVersion
50	            };
51	        } else {
52	            req.user = decoded;
53	        }
54	
55	        next();
56	    } catch (err) {
57	        console.error("verifyToken account lookup failed:", err.message);
58	        return res.status(500).json({ message: "Authentication service unavailable." });
59	    }
60	};
61	
62	// Canonical role values — must match the Sequelize ENUM in models/User.js.
63	const ROLES = Object.freeze({ FM: 'FM', STAFF: 'Staff', TENANT: 'Tenant' });
64	
65	// Role-gate middleware. Use AFTER verifyToken (needs req.user populated).
66	//   router.get('/admin', verifyToken, requireRole('FM'), handler)
67	//   router.get('/ops',   verifyToken, requireRole('FM', 'Staff'), handler)
68	// 401 = no/invalid token (handled by verifyToken); 403 = valid token, wrong role.
69	const requireRole = (...allowedRoles) => (req, res, next) => {
70	    if (!req.user) {
71	        return res.status(401).json({ message: "Authentication required." });
72	    }
73	    if (!allowedRoles.includes(req.user.role)) {
74	        return res.status(403).json({ message: "Insufficient permissions for this resource." });
75	    }
76	    next();
77	};
78	
79	// Allows a trusted internal service (the Python AI engine) to call an endpoint using a
80	// shared secret header instead of a user JWT, OR a logged-in user with an allowed role.
81	//   router.post('/detection-alerts', verifyServiceOrRole('FM', 'Staff'), handler)
82	// Used only where a backend service posts data server-to-server (e.g. AI-generated alerts).
83	const verifyServiceOrRole = (...allowedRoles) => (req, res, next) => {
84	    const serviceKey = req.headers['x-service-key'];
85	    if (serviceKey && process.env.AI_SERVICE_KEY && serviceKey === process.env.AI_SERVICE_KEY) {
86	        return next();
87	    }
88	    return verifyToken(req, res, () => requireRole(...allowedRoles)(req, res, next));
89	};
90	
91	module.exports = { verifyToken, requireRole, verifyServiceOrRole, ROLES };
