5	const request = require("supertest");
6	const jwt = require("jsonwebtoken");
7	
8	const DB_USERS = {
9	  1: { id: 1, role: "FM", isActive: true },
10	  2: { id: 2, role: "Tenant", isActive: true },
11	  3: { id: 3, role: "Staff", isActive: true },
12	};
