40	    const res = await request(app).get("/fm-only").set("Authorization", `Bearer ${token(ROLES.STAFF)}`);
41	    expect(res.status).toBe(403);
42	  });
43	
44	  test("FM on FM-only → 200", async () => {
45	    const res = await request(app).get("/fm-only").set("Authorization", `Bearer ${token(ROLES.FM)}`);
46	    expect(res.status).toBe(200);
