63	    expect(log.type).toBe("Gantry Access");
64	    expect(log.severity).toBe("safe");
65	    expect(log.personnelName).toBe("Tan Xiu Li, Felicia");
66	    expect(log.matchedUserId).toBe(25);
67	    expect(log.cameraLocation).toBe("Biometric Gantry");
68	    expect(log.reviewStatus).toBe("Resolved");
69	    expect(JSON.stringify(log)).not.toMatch(/faceVector|embedding/i);
