72	  test("repeated scans within the cooldown do not duplicate the access log", async () => {
73	    mockUser.findByPk.mockResolvedValue(activeUser);
74	    mockAttendance.findAll.mockResolvedValue([]);
75	    mockAttendance.create.mockResolvedValue({ timestamp: new Date(), type: "IN" });
