122	describe("DELETE /user/:id — offboarding refreshes the AI cache non-fatally", () => {
123	  const target = {
124	    id: 60, name: "Leaving Staff", managerId: 50,
125	    update: jest.fn().mockResolvedValue(true),
126	    destroy: jest.fn().mockResolvedValue(true),
127	  };
128	
129	  beforeEach(() => {
130	    jest.clearAllMocks();
131	    // findByPk is called for the requester (authenticateToken) AND the target.
132	    mockUser.findByPk.mockImplementation((id) =>
133	      Promise.resolve(String(id) === "60" ? target : { id: 1, role: "FM", isActive: true })
134	    );
135	    mockAttendance.destroy.mockResolvedValue(1);
136	    mockSecurityLog.update.mockResolvedValue([0]);
137	  });
138	
139	  test("offboarding requests a FastAPI /refresh so the wiped template leaves the cache", async () => {
140	    const res = await request(app).delete("/user/60").set("Authorization", `Bearer ${fmToken}`);
141	    expect(res.status).toBe(200);
142	    expect(target.update).toHaveBeenCalledWith({ faceVector: null, isEnrolled: false });
143	    expect(mockAxios.get).toHaveBeenCalledWith(
144	      expect.stringMatching(/\/refresh$/),
145	      expect.objectContaining({ headers: expect.objectContaining({ "X-AI-Service-Key": expect.any(String) }) })
146	    );
147	  });
148	
149	  test("a failed refresh is NON-FATAL — offboarding still succeeds", async () => {
150	    mockAxios.get.mockRejectedValueOnce(new Error("AI offline"));
151	    const res = await request(app).delete("/user/60").set("Authorization", `Bearer ${fmToken}`);
152	    expect(res.status).toBe(200);
153	    expect(target.destroy).toHaveBeenCalled();
154	  });
155	});
156	
157	describe("Cloud server binding", () => {
158	  test("PORT (cloud) wins, then APP_PORT, then 5001", () => {
159	    expect(resolvePort({ PORT: "8080", APP_PORT: "5001" })).toBe(8080);
160	    expect(resolvePort({ APP_PORT: "5001" })).toBe(5001);
161	    expect(resolvePort({})).toBe(5001);
162	  });
163	
164	  test("binds 0.0.0.0 by default — never exclusively 127.0.0.1", () => {
165	    expect(resolveHost({})).toBe("0.0.0.0");
166	    expect(resolveHost({ HOST: "127.0.0.1" })).toBe("127.0.0.1"); // explicit override allowed
167	  });
168	});
