1	const express = require('express');
2	const router = express.Router();
3	const crypto = require('crypto');
4	const { Op } = require('sequelize');
5	const { Booking, User } = require('../models');
6	const { verifyToken, requireRole } = require('../middlewares/auth');
7	const whatsapp = require('../services/whatsappService');
8	
9	const STATUSES = ['Pending', 'Confirmed', 'Arrived', 'Completed', 'Cancelled'];
10	
11	function genRef() {
12	    return `FG-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
13	}
14	
15	// Resolve which tenant/unit a booking belongs to, based on who is creating it:
16	//   Tenant → their own id; Staff → their managerId (the tenant they work for); FM → optional body.tenantId.
17	// Returns null if it cannot be determined (FM with no tenantId, or Staff with no manager).
18	async function resolveTenantId(user, bodyTenantId) {
19	    if (user.role === 'Tenant') return user.id;
20	    if (user.role === 'Staff') {
21	        const staff = await User.findByPk(user.id, { attributes: ['managerId'] });
22	        return staff?.managerId ?? null;
23	    }
24	    return bodyTenantId || null; // FM
25	}
26	
27	// ---------------------------------------------------------------------------
28	// CREATE — FM, Tenant, or Staff create a loading-bay booking request. (400 on bad input)
29	// Staff may book on behalf of their tenant/unit (booking is linked to their managerId).
30	// ---------------------------------------------------------------------------
31	router.post('/create', verifyToken, requireRole('FM', 'Tenant', 'Staff'), async (req, res) => {
32	    try {
33	        const {
34	            transport_company, license_plate, driver_phone, loading_bay,
35	            driver_name, slot_start, slot_end, notes, tenant_name
36	        } = req.body;
37	
38	        const missing = ['transport_company', 'license_plate', 'driver_phone', 'loading_bay']
39	            .filter(f => !req.body[f] || !String(req.body[f]).trim());
40	        if (missing.length) {
41	            return res.status(400).json({ error: `Missing required field(s): ${missing.join(', ')}.` });
42	        }
43	        if (!/^[+\d][\d\s-]{6,}$/.test(String(driver_phone))) {
44	            return res.status(400).json({ error: 'driver_phone is not a valid phone number.' });
45	        }
46	
47	        // Optional slot-conflict guard (409) when a time window is supplied.
48	        if (slot_start && slot_end) {
49	            if (new Date(slot_end) <= new Date(slot_start)) {
50	                return res.status(400).json({ error: 'slot_end must be after slot_start.' });
51	            }
52	            const clash = await Booking.findOne({
53	                where: {
54	                    loading_bay,
55	                    status: { [Op.ne]: 'Cancelled' },
56	                    slot_start: { [Op.lt]: new Date(slot_end) },
57	                    slot_end: { [Op.gt]: new Date(slot_start) }
58	                }
59	            });
60	            if (clash) {
61	                return res.status(409).json({ error: `${loading_bay} is already booked for that time window.` });
62	            }
63	        }
64	
65	        // Link the booking to a tenant/unit so the right people can see it
66	        // (Tenant → self, Staff → their managerId, FM → optional body.tenantId).
67	        const tenantId = await resolveTenantId(req.user, req.body.tenantId);
68	
69	        const booking = await Booking.create({
70	            booking_ref: genRef(),
71	            transport_company,
72	            license_plate,
73	            driver_phone,
74	            loading_bay,
75	            driver_name: driver_name || null,
76	            slot_start: slot_start || null,
77	            slot_end: slot_end || null,
78	            notes: notes || null,
79	            tenant_name: tenant_name || null,
80	            tenantId,
81	            status: 'Pending'
82	        });
83	
84	        // Confirmation to the driver — non-fatal (must never fail the booking).
85	        let whatsappResult = null;
86	        try {
87	            whatsappResult = await whatsapp.sendBookingCreated(booking);
88	        } catch (waErr) {
89	            console.error('WhatsApp notify failed (non-fatal):', waErr.message);
90	        }
91	
92	        res.status(201).json({ message: 'Booking created.', booking, whatsapp: whatsappResult });
93	    } catch (err) {
94	        console.error('Booking create error:', err);
95	        res.status(500).json({ error: 'Internal server error while creating booking.' });
96	    }
97	});
