99	// ---------------------------------------------------------------------------
100	// READ (list) — FM sees all; Tenant sees own unit; Staff sees their unit's bookings.
101	// ---------------------------------------------------------------------------
102	router.get('/', verifyToken, async (req, res) => {
103	    try {
104	        const where = {};
105	        if (req.user.role === 'Tenant') {
106	            where.tenantId = req.user.id;
107	        } else if (req.user.role === 'Staff') {
108	            // Staff only see bookings for the tenant/unit they belong to.
109	            const tenantId = await resolveTenantId(req.user, null);
110	            where.tenantId = tenantId ?? -1; // -1 → matches nothing if no manager set
111	        }
112	        // FM → no filter (all bookings)
113	        const bookings = await Booking.findAll({ where, order: [['createdAt', 'DESC']], limit: 100 });
114	        res.status(200).json(bookings);
115	    } catch (err) {
116	        console.error('Booking list error:', err);
117	        res.status(500).json({ error: 'Could not retrieve bookings.' });
118	    }
119	});
