121	// READ (all) — FM-only compat alias (unscoped). Declared BEFORE '/:ref'.
122	router.get('/all', verifyToken, requireRole('FM'), async (req, res) => {
123	    try {
124	        const bookings = await Booking.findAll({ order: [['createdAt', 'DESC']], limit: 100 });
125	        res.status(200).json(bookings);
126	    } catch (err) {
127	        console.error('Booking list error:', err);
128	        res.status(500).json({ error: 'Could not retrieve bookings.' });
129	    }
130	});
