132	// ---------------------------------------------------------------------------
133	// UPDATE status — FM only (facility-level: Pending → Confirmed → Arrived → Completed).
134	// Confirmed → WhatsApp slot confirmation. Completed → auto next-in-line alert.
135	// ---------------------------------------------------------------------------
136	router.patch('/:id/status', verifyToken, requireRole('FM'), async (req, res) => {
137	    try {
138	        const { status } = req.body;
139	        if (!STATUSES.includes(status)) {
140	            return res.status(400).json({ error: `status must be one of: ${STATUSES.join(', ')}.` });
141	        }
142	
143	        const booking = await Booking.findByPk(req.params.id);
144	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
145	
146	        await booking.update({ status });
147	
148	        let whatsappResult = null;
149	        let nextInLine = null;
150	
151	        // All WhatsApp sends are non-fatal — a failure must never fail the status update.
152	        try {
153	            if (status === 'Confirmed') {
154	                whatsappResult = await whatsapp.sendBookingConfirmed(booking);
155	            } else if (status === 'Arrived') {
156	                whatsappResult = await whatsapp.sendBookingArrived(booking);
157	            } else if (status === 'Cancelled') {
158	                whatsappResult = await whatsapp.sendBookingCancelled(booking);
159	            } else if (status === 'Completed') {
160	                // Notify the leaving driver, then alert the next waiting booking for the same bay.
161	                whatsappResult = await whatsapp.sendBookingCompleted(booking);
162	                const next = await Booking.findOne({
163	                    where: { loading_bay: booking.loading_bay, status: { [Op.in]: ['Pending', 'Confirmed'] } },
164	                    order: [['slot_start', 'ASC'], ['createdAt', 'ASC']]
165	                });
166	                if (next) {
167	                    await whatsapp.sendNextInLine(next);
168	                    nextInLine = next.booking_ref;
169	                }
170	            }
171	        } catch (waErr) {
172	            console.error('WhatsApp notify failed (non-fatal):', waErr.message);
173	        }
174	
175	        res.status(200).json({ message: `Booking ${status}.`, booking, whatsapp: whatsappResult, nextInLine });
176	    } catch (err) {
177	        console.error('Booking status error:', err);
178	        res.status(500).json({ error: 'Could not update booking status.' });
179	    }
180	});
