183	// EDIT — manual booking update. FM may edit any booking; a Tenant may edit
184	// only their own unit's bookings. Closed bookings cannot be edited.
185	// Editable fields only — status changes stay on /:id/status and /:ref/gate-scan,
186	// and cancellation remains the soft-delete on /:id/cancel.
187	// ---------------------------------------------------------------------------
188	const EDITABLE_FIELDS = [
189	    'transport_company', 'driver_name', 'driver_phone', 'license_plate',
190	    'loading_bay', 'slot_start', 'slot_end', 'notes'
