356	        const targetId = staffMember.id;
357	        const targetName = staffMember.name;
358	
359	        // --- PDPA-COMPLIANT OFF-BOARDING (data minimisation, TRANSACTIONAL) ---
360	        // Every step commits together or not at all — no half-deleted accounts.
361	        await sequelize.transaction(async (t) => {
362	            // 1. Explicitly wipe the protected biometric template first, so it
363	            //    can never linger even if a later step fails and is retried.
364	            await staffMember.update({ faceVector: null, isEnrolled: false }, { transaction: t });
365	
366	            // 2. Hard-delete their attendance trail.
367	            await Attendance.destroy({ where: { userId: targetId }, transaction: t });
368	
369	            // 3. Anonymise — not delete — the security/access logs that referenced
370	            //    this person. The events stay for the security audit trail, but the
371	            //    personal linkage (name + matched user id) is stripped, and any
372	            //    description containing their name is replaced with a neutral one.
373	            await SecurityLog.update(
374	                { personnelName: null, matchedUserId: null },
375	                {
376	                    where: { [Op.or]: [{ personnelName: targetName }, { matchedUserId: targetId }] },
377	                    transaction: t
378	                }
379	            );
380	            await SecurityLog.update(
381	                { desc: 'Access event retained for audit — personnel record removed and identity anonymised.' },
382	                { where: { desc: { [Op.like]: `%${targetName}%` } }, transaction: t }
383	            );
384	
385	            // 4. Bookings keep their operational audit trail (ref, company,
386	            //    schedule, gate scans) but lose the personal account linkage.
387	            await Booking.update(
388	                { tenantId: null },
389	                { where: { tenantId: targetId }, transaction: t }
390	            );
391	
392	            // 5. Hard-delete the user row itself.
393	            await staffMember.destroy({ transaction: t });
394	        });
395	
396	        // 4. Ask the AI service to reload its known-face cache so the wiped
397	        //    template disappears from memory immediately. NON-FATAL: the
398	        //    off-boarding already succeeded; the cache also reloads on restart.
399	        try {
400	            const faceAiUrl = process.env.FACE_AI_URL || 'http://127.0.0.1:8501';
401	            await axios.get(`${faceAiUrl}/refresh`, {
